from pathlib import Path
import json, math, csv, time
import numpy as np
import matplotlib; matplotlib.use('Agg'); import matplotlib.pyplot as plt

ROOT=Path(__file__).resolve().parent; IN=ROOT/'results'/'surrogate_2d_pilot_recompute_train3_20261012'; OUT=ROOT/'results'/f'surrogate_2d_pilot_train3_band_energy_{time.strftime("%Y%m%d_%H%M%S")}'
BANDS=[(250,500),(500,1000),(1000,2000),(2000,4000)]; FS=16000; FLOOR=1e-12
def fft_energy(rir,nfft,lo=None,hi=None):
 x=np.zeros(nfft); x[:len(rir)]=rir; X=np.fft.rfft(x); f=np.fft.rfftfreq(nfft,1/FS); w=np.ones(len(X)); w[0]=1; w[-1]=1 if nfft%2==0 else 2; w[1:-1]=2 if nfft%2==0 else 2; sel=np.ones(len(f),bool) if lo is None else ((f>=lo)&(f<hi)); return float(np.sum(w[sel]*np.abs(X[sel])**2)/nfft)
def main():
 OUT.mkdir(parents=True,exist_ok=False); reports=[]; all_ids=['sample_0000','sample_0002','sample_0005'];
 with (ROOT/'data'/'surrogate_2d'/'dataset'/'metadata.csv').open(encoding='utf-8-sig') as f: meta={r['sample_id']:r for r in csv.DictReader(f)}
 for sid in all_ids:
  z=np.load(IN/f'{sid}_raw.npz'); rir=z['rir']; lengths=z['rir_lengths']; valid=z['valid_mask'].reshape(-1); idx=z['receiver_indices']; orig=z['original_map'].reshape(-1); stored=z['normalized_map'].reshape(-1); coords=z['receiver_positions']; maxlen=int(lengths.max()); nfft=1<<(maxlen-1).bit_length(); nfft2=2*nfft; actual=[rir[k,:int(lengths[k])] for k in range(len(lengths))]; broadband=np.array([np.sum(x*x) for x in actual]); total_fft=np.array([fft_energy(x,nfft) for x in actual]); bands={}; bands2={}
  for lo,hi in BANDS:
   key=f'{lo}-{hi} Hz'; e=np.array([fft_energy(x,nfft,lo,hi) for x in actual]); e2=np.array([fft_energy(x,nfft2,lo,hi) for x in actual]); rawdb=10*np.log10(np.maximum(e,FLOOR)); rawdb2=10*np.log10(np.maximum(e2,FLOOR)); grid=np.full(400,np.nan); grid2=np.full(400,np.nan); grid[valid]=rawdb; grid2[valid]=rawdb2; rel=grid-np.nanmax(grid); common=grid-10*np.log10(np.nanmax(broadband)); bands[key]={'energy':e,'raw_db':grid,'relative_db':rel,'common_broadband_db':common}; bands2[key]=e2
  band_sum=np.sum([bands[f'{lo}-{hi} Hz']['energy'] for lo,hi in BANDS],axis=0); band_sum2=np.sum([bands2[f'{lo}-{hi} Hz'] for lo,hi in BANDS],axis=0); e2504=np.array([fft_energy(x,nfft,250,4000) for x in actual]); e2504_2=np.array([fft_energy(x,nfft2,250,4000) for x in actual]);
  maps=np.full((len(BANDS)+1,20,20),np.nan); common=np.full_like(maps,np.nan); maps[0]=stored.reshape(20,20); common[0]=stored.reshape(20,20)
  for j,(lo,hi) in enumerate(BANDS,1): maps[j]=bands[f'{lo}-{hi} Hz']['relative_db'].reshape(20,20); common[j]=bands[f'{lo}-{hi} Hz']['common_broadband_db'].reshape(20,20)
  rr=meta[sid]; geom=np.array([float(rr[k]) for k in ('speaker_x','speaker_y','obstacle_x','obstacle_y','obstacle_w','obstacle_l')]); np.savez_compressed(OUT/f'{sid}_band_maps.npz',sample_id=sid,band_edges_hz=np.asarray(BANDS),frequencies_hz=np.fft.rfftfreq(nfft,1/FS),energies=np.stack([bands[f'{lo}-{hi} Hz']['energy'] for lo,hi in BANDS]),raw_db=np.stack([bands[f'{lo}-{hi} Hz']['raw_db'] for lo,hi in BANDS]),common_broadband_db=np.stack([bands[f'{lo}-{hi} Hz']['common_broadband_db'] for lo,hi in BANDS]),broadband_energy=broadband,original_broadband_map=orig,original_normalized_map=stored,valid_mask=valid,obstacle_mask=z['obstacle_mask'],receiver_positions=coords,receiver_indices=idx,rir_lengths=lengths,n_fft=nfft,n_fft_double=nfft2,scene_geometry=geom)
  fig,axs=plt.subplots(1,5,figsize=(18,4),constrained_layout=True); vals=[stored.reshape(20,20)]+[bands[f'{lo}-{hi} Hz']['relative_db'].reshape(20,20) for lo,hi in BANDS]; lo=min(np.nanmin(v) for v in vals); hi=0
  for ax,v,title in zip(axs,vals,['Broadband']+[f'{a}-{b} Hz' for a,b in BANDS]): im=ax.imshow(v,origin='lower',cmap='viridis',vmin=lo,vmax=hi); ax.add_patch(plt.Rectangle((float(rr['obstacle_x'])/.5-.5,float(rr['obstacle_y'])/.5-.5),float(rr['obstacle_w'])/.5,float(rr['obstacle_l'])/.5,fill=False,edgecolor='white',lw=1)); ax.scatter([float(rr['speaker_x'])/.5-1],[float(rr['speaker_y'])/.5-1],marker='*',color='red',s=35); ax.set_title(title); ax.set_xlabel('x index'); ax.set_ylabel('y index'); fig.colorbar(im,ax=ax,shrink=.75)
  fig.suptitle(f'{sid} | individual band maxima normalized to 0 dB'); fig.savefig(OUT/f'{sid}_relative_maps.png',dpi=170); plt.close(fig)
  fig,axs=plt.subplots(1,4,figsize=(15,4),constrained_layout=True); vals=[bands[f'{a}-{b} Hz']['common_broadband_db'].reshape(20,20) for a,b in BANDS]; lo=min(np.nanmin(v) for v in vals); hi=max(np.nanmax(v) for v in vals)
  for ax,v,(a,b) in zip(axs,vals,BANDS): im=ax.imshow(v,origin='lower',cmap='viridis',vmin=lo,vmax=hi); ax.add_patch(plt.Rectangle((float(rr['obstacle_x'])/.5-.5,float(rr['obstacle_y'])/.5-.5),float(rr['obstacle_w'])/.5,float(rr['obstacle_l'])/.5,fill=False,edgecolor='white',lw=1)); ax.scatter([float(rr['speaker_x'])/.5-1],[float(rr['speaker_y'])/.5-1],marker='*',color='red',s=35); ax.set_title(f'{a}-{b} Hz'); ax.set_xlabel('x index'); ax.set_ylabel('y index'); fig.colorbar(im,ax=ax,shrink=.75)
  fig.suptitle(f'{sid} | common broadband maximum-energy reference'); fig.savefig(OUT/f'{sid}_common_maps.png',dpi=170); plt.close(fig)
  reports.append({'sample_id':sid,'n_fft':nfft,'n_fft_double':nfft2,'valid_cells':int(valid.sum()),'energy_share':[float(e.sum()/broadband.sum()) for e in [bands[f'{a}-{b} Hz']['energy'] for a,b in BANDS]],'checks':{'parseval_max_relative_error':float(np.max(abs(total_fft-broadband)/np.maximum(broadband,FLOOR))),'four_band_vs_250_4000_max_relative_error':float(np.max(abs(band_sum-e2504)/np.maximum(e2504,FLOOR))),'nfft2_band_max_relative_change':float(np.max(abs(band_sum2-band_sum)/np.maximum(band_sum,FLOOR))),'nfft2_relative_map_max_change_db':float(max(np.nanmax(abs((10*np.log10(np.maximum(bands2[f'{a}-{b} Hz'],FLOOR))-np.nanmax(10*np.log10(np.maximum(bands2[f'{a}-{b} Hz'],FLOOR))))-(bands[f'{a}-{b} Hz']['relative_db'][valid]))) for a,b in BANDS)),'stored_map_max_abs_error_db':float(np.nanmax(abs(stored[valid]-orig[valid]))),'mask_match':bool(np.array_equal(np.isnan(orig),z['obstacle_mask'].reshape(-1))),'nonfinite_valid':int(np.sum(~np.isfinite(orig[valid])))}})
  with (OUT/'band_summary.csv').open('w',newline='',encoding='utf-8-sig') as f:
   w=csv.writer(f); w.writerow(['sample_id','band','energy_share']); [w.writerow([sid,f'{a}-{b} Hz',reports[-1]['energy_share'][j]]) for j,(a,b) in enumerate(BANDS)]
 (OUT/'metrics.json').write_text(json.dumps({'input_folder':str(IN),'settings':{'fs_hz':FS,'bands_hz':BANDS,'boundary':'[low,high)','n_fft':'next power of two >= max actual RIR length','one_sided_parseval':'sum(weight*abs(rfft)^2)/n_fft; DC/Nyquist weight 1, other bins 2','floor':FLOOR,'no_rir_recompute':True},'scenes':reports,'limitations':['FFT-bin integration, not Butterworth filtering.','Raw dB is relative simulator energy, not absolute SPL or measured pressure.']},ensure_ascii=False,indent=2),encoding='utf-8')
 (OUT/'README.md').write_text('# Pilot train-3 band energy maps\n\n저장된 pilot NPZ의 raw RIR만 사용했습니다. 실제 RIR 길이로 자른 뒤 공통 zero-padding과 rFFT를 적용했고, 단측 스펙트럼 Parseval 가중치를 사용했습니다. 대역은 [하한, 상한)입니다. 각 대역별 0 dB 지도와 광대역 최대 에너지를 공통 기준으로 한 지도를 저장했습니다. FFT 적분 결과는 기존 Butterworth 필터 분석과 동일한 수치로 간주하지 않습니다. raw dB는 절대 SPL이나 실측 음압이 아닙니다. 장애물 내부는 NaN입니다.\n',encoding='utf-8')
 print(OUT)
if __name__=='__main__': main()
